# INTERVAL 'n' <unit> literals. pg_query deparses them as 'n'::interval <unit>,
# which DuckDB reads as n seconds. The normalizer writes to_<unit>s(n).

# Select list.
same SELECT id, d + INTERVAL '400' DAY FROM t ORDER BY id
same SELECT id, ts + INTERVAL '3' HOUR FROM t ORDER BY id
same SELECT id, ts - INTERVAL '90' MINUTE FROM t ORDER BY id
same SELECT id, ts + INTERVAL '45' SECOND FROM t ORDER BY id
same SELECT id, d + INTERVAL '1' MONTH FROM t ORDER BY id
same SELECT id, d - INTERVAL '2' YEAR FROM t ORDER BY id
same SELECT id, tz + INTERVAL '1' DAY FROM t ORDER BY id
same SELECT INTERVAL '400' DAY, INTERVAL '3' MONTH, INTERVAL '2' YEAR FROM t WHERE id = 1
same SELECT INTERVAL '5' HOUR, INTERVAL '7' MINUTE, INTERVAL '9' SECOND FROM t WHERE id = 1
same SELECT INTERVAL '-3' DAY, INTERVAL '1.5' DAY, INTERVAL '0.5' DAY, INTERVAL ' 3 ' DAY FROM t WHERE id = 1
same SELECT INTERVAL '1e2' SECOND, INTERVAL '+3' DAY, INTERVAL '2.5' HOUR, INTERVAL '1.5' MINUTE FROM t WHERE id = 1
same SELECT INTERVAL '1.7' YEAR, INTERVAL '-1.5' MONTH, INTERVAL '0.25' SECOND FROM t WHERE id = 1
same SELECT id, iv + INTERVAL '1' DAY FROM t ORDER BY id
same SELECT id, iv - INTERVAL '1' HOUR FROM t ORDER BY id
same SELECT id, iv > INTERVAL '30' DAY FROM t ORDER BY id
same SELECT id, iv * 2 + INTERVAL '1' MONTH FROM t ORDER BY id
same SELECT EXTRACT(day FROM INTERVAL '400' DAY) FROM t WHERE id = 1
same SELECT EXTRACT(hour FROM INTERVAL '30' HOUR), EXTRACT(month FROM INTERVAL '14' MONTH) FROM t WHERE id = 1
same SELECT INTERVAL '1' DAY = INTERVAL '24' HOUR FROM t WHERE id = 1
same SELECT INTERVAL '1' YEAR = INTERVAL '12' MONTH, INTERVAL '1' HOUR = INTERVAL '60' MINUTE FROM t WHERE id = 1
same SELECT id, date_add(d, INTERVAL '10' DAY) FROM t ORDER BY id
same SELECT id, INTERVAL '3' DAY * a FROM t ORDER BY id
same SELECT id, (ts + INTERVAL '1' HOUR)::DATE FROM t ORDER BY id
same SELECT id, CAST(INTERVAL '2' DAY AS VARCHAR) FROM t ORDER BY id
same SELECT id, CAST(d + INTERVAL '1' MONTH AS VARCHAR) FROM t ORDER BY id
same SELECT ARRAY[INTERVAL '1' DAY, INTERVAL '2' HOUR] FROM t WHERE id = 1
same SELECT id, date_trunc('month', d + INTERVAL '20' DAY) FROM t ORDER BY id
same SELECT id, d + INTERVAL '400' DAY AS due FROM t ORDER BY due, id
same SELECT id, ts + INTERVAL '3' HOUR AS later, later - INTERVAL '1' HOUR FROM t ORDER BY id
same SELECT max(d) + INTERVAL '1' DAY FROM t
same SELECT min(ts) - INTERVAL '6' MONTH, max(iv) + INTERVAL '1' SECOND FROM t
same SELECT id, d - DATE '2024-01-01' > 400, d > DATE '2024-01-01' + INTERVAL '400' DAY FROM t ORDER BY id

# WHERE.
same SELECT id FROM t WHERE iv >= INTERVAL '400' DAY ORDER BY id
same SELECT id FROM t WHERE iv < INTERVAL '3' HOUR ORDER BY id
same SELECT id FROM t WHERE iv > INTERVAL '2' MONTH ORDER BY id
same SELECT id FROM t WHERE iv = INTERVAL '30' SECOND ORDER BY id
same SELECT id FROM t WHERE iv >= INTERVAL '90' MINUTE ORDER BY id
same SELECT id FROM t WHERE iv > INTERVAL '1' YEAR ORDER BY id
same SELECT id FROM t WHERE d > DATE '2026-03-01' - INTERVAL '400' DAY ORDER BY id
same SELECT id FROM t WHERE ts + INTERVAL '30' MINUTE > TIMESTAMP '2024-06-30 23:59:59' ORDER BY id
same SELECT id FROM t WHERE d < DATE '2026-01-01' - INTERVAL '1' YEAR ORDER BY id
same SELECT id FROM t WHERE iv BETWEEN INTERVAL '1' HOUR AND INTERVAL '2' DAY ORDER BY id
same SELECT id FROM t WHERE d + INTERVAL '2' MONTH BETWEEN DATE '2024-03-01' AND DATE '2025-05-01' ORDER BY id
same SELECT id FROM t WHERE ts > TIMESTAMP '2026-03-01 00:00:00' - INTERVAL '3' YEAR ORDER BY id
same SELECT id FROM t WHERE iv IN (INTERVAL '1' DAY, INTERVAL '2' HOUR) ORDER BY id
same SELECT id FROM t WHERE tz < TIMESTAMPTZ '2025-01-01 00:00:00+00' + INTERVAL '10' DAY ORDER BY id
same SELECT id FROM t WHERE iv IS DISTINCT FROM INTERVAL '1' DAY ORDER BY id
same SELECT id FROM t WHERE NOT iv > INTERVAL '1' DAY ORDER BY id

# Nested: CASE, FILTER, window frames, subqueries, CTEs.
same SELECT id, CASE WHEN iv > INTERVAL '30' DAY THEN 'long' ELSE 'short' END FROM t ORDER BY id
same SELECT id, CASE WHEN d > DATE '2025-01-01' THEN d - INTERVAL '1' YEAR ELSE d + INTERVAL '1' YEAR END FROM t ORDER BY id
same SELECT count(*) FILTER (WHERE d > DATE '2026-03-01' - INTERVAL '400' DAY) FROM t
same SELECT count(*) FILTER (WHERE iv < INTERVAL '1' DAY), count(*) FILTER (WHERE iv >= INTERVAL '1' DAY) FROM t
same SELECT id, count(*) OVER (ORDER BY d RANGE BETWEEN INTERVAL '400' DAY PRECEDING AND CURRENT ROW) FROM t ORDER BY id
same SELECT id, sum(a) OVER (ORDER BY ts RANGE BETWEEN INTERVAL '1' YEAR PRECEDING AND CURRENT ROW) FROM t ORDER BY id
same SELECT id, count(*) OVER (ORDER BY ts RANGE BETWEEN INTERVAL '12' HOUR PRECEDING AND INTERVAL '12' HOUR FOLLOWING) FROM t ORDER BY id
same SELECT id, count(*) OVER w FROM t WINDOW w AS (ORDER BY d RANGE BETWEEN INTERVAL '30' DAY PRECEDING AND CURRENT ROW) ORDER BY id
same SELECT id FROM t WHERE id IN (SELECT id FROM u WHERE iv >= INTERVAL '1' DAY) ORDER BY id
same SELECT id FROM t WHERE EXISTS (SELECT 1 FROM u WHERE u.id = t.id AND u.d > t.d + INTERVAL '6' DAY) ORDER BY id
same SELECT (SELECT max(d) FROM u) - INTERVAL '30' DAY FROM t WHERE id = 1
same WITH c AS (SELECT id, d + INTERVAL '6' MONTH AS due FROM t) SELECT id, due FROM c ORDER BY id
same WITH c AS (SELECT id FROM t WHERE iv > INTERVAL '1' HOUR) SELECT count(*) FROM c
same SELECT x.id, x.later FROM (SELECT id, ts + INTERVAL '2' DAY AS later FROM t) x ORDER BY x.id
same SELECT id, coalesce(iv, INTERVAL '0' SECOND) + INTERVAL '5' MINUTE FROM t ORDER BY id
same SELECT t.id FROM t JOIN u ON u.id = t.id AND u.d = t.d + INTERVAL '7' DAY ORDER BY t.id
same SELECT id, list_transform(l, x -> d + to_days(x)) FROM t ORDER BY id

# Explicit casts keep a typmod both parsers ignore.
same SELECT id, '1'::interval day FROM t ORDER BY id
same SELECT CAST('5' AS INTERVAL DAY), '1 day'::interval hour FROM t WHERE id = 1
same SELECT id, CAST(iv AS INTERVAL DAY) FROM t ORDER BY id
same SELECT ARRAY['1'::interval day] FROM t WHERE id = 1
same SELECT id FROM t WHERE iv > '1 hour'::interval hour ORDER BY id

# Interval text, to_<unit>s and AS after the literal stay as they are.
same SELECT id, INTERVAL '3 days' FROM t ORDER BY id
same SELECT id, ts + INTERVAL '3 weeks' FROM t ORDER BY id
same SELECT id FROM t WHERE iv > INTERVAL '1 hour' ORDER BY id
same SELECT to_days(3), to_weeks(2), to_hours(5), to_months(2) FROM t WHERE id = 1
same SELECT id, d + to_weeks(3) FROM t ORDER BY id
same SELECT id FROM t WHERE ts > TIMESTAMP '2024-01-01' + to_weeks(2) ORDER BY id
same SELECT id, INTERVAL '3' AS week FROM t ORDER BY id

# WEEK, plural units and the units pg_query does not know: it reads the
# unit as an alias. Hint: INTERVAL '3 weeks' or to_weeks(3).
ERR_UNSUPPORTED_SYNTAX SELECT id, ts + INTERVAL '3' WEEK FROM t ORDER BY id
ERR_UNSUPPORTED_SYNTAX SELECT INTERVAL '1' WEEK FROM t
ERR_UNSUPPORTED_SYNTAX SELECT INTERVAL '3' DAYS FROM t
ERR_UNSUPPORTED_SYNTAX SELECT INTERVAL '3' HOURS FROM t
ERR_UNSUPPORTED_SYNTAX SELECT INTERVAL '2' YEARS FROM t
ERR_UNSUPPORTED_SYNTAX SELECT INTERVAL '2' MONTHS FROM t
ERR_UNSUPPORTED_SYNTAX SELECT INTERVAL '2' MINUTES FROM t
ERR_UNSUPPORTED_SYNTAX SELECT INTERVAL '2' SECONDS FROM t
ERR_UNSUPPORTED_SYNTAX SELECT INTERVAL '2' WEEKS FROM t
ERR_UNSUPPORTED_SYNTAX SELECT INTERVAL '1' QUARTER FROM t
ERR_UNSUPPORTED_SYNTAX SELECT INTERVAL '3' MILLISECOND FROM t
ERR_UNSUPPORTED_SYNTAX SELECT INTERVAL '3' MICROSECOND FROM t
ERR_UNSUPPORTED_SYNTAX SELECT INTERVAL '3' MILLISECONDS FROM t
ERR_UNSUPPORTED_SYNTAX SELECT INTERVAL '1' DECADE FROM t
ERR_UNSUPPORTED_SYNTAX SELECT INTERVAL '1' CENTURY FROM t
ERR_UNSUPPORTED_SYNTAX SELECT INTERVAL '1' MILLENNIUM FROM t
ERR_UNSUPPORTED_SYNTAX SELECT id, d + INTERVAL '2' WEEKS FROM t ORDER BY id
ERR_UNSUPPORTED_SYNTAX SELECT id, (SELECT INTERVAL '1' WEEK) FROM t ORDER BY id
ERR_UNSUPPORTED_SYNTAX WITH c AS (SELECT INTERVAL '2' QUARTER FROM t) SELECT * FROM c

# In WHERE and inside expressions pg_query cannot parse them at all. Nor a
# DuckDB list literal.
ERR_SYNTAX SELECT [INTERVAL '1' MONTH, INTERVAL '3' MINUTE] FROM t WHERE id = 1
ERR_SYNTAX SELECT id FROM t WHERE iv > INTERVAL '1' WEEK
ERR_SYNTAX SELECT id FROM t WHERE ts > TIMESTAMP '2024-01-01' + INTERVAL '3' DAYS
ERR_SYNTAX SELECT id, CASE WHEN iv > INTERVAL '1' WEEK THEN 1 END FROM t

# Ranges and precisions: DuckDB cannot parse them.
ERR_SYNTAX SELECT INTERVAL '02:03' HOUR TO MINUTE FROM t
ERR_SYNTAX SELECT INTERVAL '1' DAY TO SECOND FROM t
ERR_SYNTAX SELECT INTERVAL '1-2' YEAR TO MONTH FROM t
ERR_SYNTAX SELECT INTERVAL '1 02' DAY TO HOUR FROM t
ERR_SYNTAX SELECT INTERVAL '3' SECOND(3) FROM t
ERR_SYNTAX SELECT INTERVAL(3) '1 day' FROM t
ERR_SYNTAX SELECT id FROM t WHERE iv > INTERVAL '02:03' HOUR TO MINUTE
ERR_SYNTAX SELECT id, CASE WHEN iv > INTERVAL '1' DAY TO SECOND THEN 1 END FROM t

# The literal casts n to DOUBLE, so interval text fails on both sides.
rawfails SELECT INTERVAL '1 day' DAY FROM t
rawfails SELECT INTERVAL '1 day 2 hours' HOUR FROM t
